CREATE TABLE IF NOT EXISTS products (
  id bigserial PRIMARY KEY,
  sku text UNIQUE NOT NULL, code text NOT NULL, category text NOT NULL,
  category_name_ar text, category_name_en text, name_ar text,
  color_name_ar text, color_name_en text, color_hex text, color_family text,
  pattern text, material text, width_cm text, length_cm text, thickness_mm text,
  notes_ar text, source_catalog text, source_page int,
  image_page text, image_swatch text
);
